(885,1641,$mw$4ECDC3B012D2606CC728B00AB02BEE97C2D80976AE91D1944C67F31BEDE93FA4$mw$,$mw$aa5c3f31b56b6bacbce725eeaae6e1b1$mw$,$mw$$mw$,$mw${"Id":1641,"StageId":2,"CategoryId":22,"Points":10,"TitleAr":"ما منوال البيانات 3، 5، 5، 5، 8، 8؟","TitleEn":"Find the mode of 3, 5, 5, 5, 8, 8.","QuestionTextAr":"ما منوال البيانات 3، 5، 5، 5، 8، 8؟","QuestionTextEn":"Find the mode of 3, 5, 5, 5, 8, 8.","DetailedSolutionAr":"القانون المستخدم: المنوال هو القيمة الأكثر تكراراً في مجموعة البيانات. نحصي التكرارات: العدد 3 ظهر مرة واحدة، والعدد 5 ظهر ثلاث مرات، والعدد 8 ظهر مرتين. أكبر تكرار هو 3 مرات للقيمة 5، لذلك المنوال = 5. لا نستخدم قانون المتوسط الحسابي لحساب المنوال.","DetailedSolutionEn":"Rule used: The mode is the data value that occurs most often. Count occurrences: 3 appears once, 5 appears three times, and 8 appears twice. The largest frequency belongs to 5, so the mode is 5. This differs from computing the arithmetic mean.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6553,"Order":1,"LatexCode":"5","IsCorrect":true},{"Id":6554,"Order":2,"LatexCode":"8","IsCorrect":false},{"Id":6555,"Order":3,"LatexCode":"3","IsCorrect":false},{"Id":6556,"Order":4,"LatexCode":"6","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"أحص تكرار كل قيمة.","En":"Count each value's occurrences."},{"Ar":"قارن التكرارات واختر القيمة الموافقة للأكبر منها.","En":"Compare frequencies and select the value with the highest frequency."}],"Title":{"Ar":"ما منوال البيانات 3، 5، 5، 5، 8، 8؟","En":"Find the mode of 3, 5, 5, 5, 8, 8."},"Points":10,"Options":[{"LatexCode":"5","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"8","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"8 يتكرر مرتين فقط.","En":"Eight occurs only twice."}},{"LatexCode":"3","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"3 يتكرر مرة واحدة فقط.","En":"Three occurs only once."}},{"LatexCode":"6","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"6 عدد المشاهدات وليس قيمة متكررة.","En":"Six is the observation count, not a repeated value."}}],"StageId":2,"Question":{"Ar":"ما منوال البيانات 3، 5، 5، 5، 8، 8؟","En":"Find the mode of 3, 5, 5, 5, 8, 8."},"Solution":{"Idea":{"Ar":"المنوال يحدد القيمة صاحبة التكرار الأكبر.","En":"The mode identifies the value with highest frequency."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نعد تكرار كل قيمة مختلفة في القائمة.","En":"Count occurrences of each distinct value in the list."},{"Ar":"$f(3)=1,\\ f(5)=3,\\ f(8)=2$","En":"$f(3)=1,\\ f(5)=3,\\ f(8)=2$"},{"Ar":"نختار القيمة ذات التكرار الأكبر، وليس عدد مرات التكرار نفسه.","En":"Choose the value with the largest frequency, not the frequency itself."}],"Result":{"Ar":"$5$","En":"$5$"},"CommonError":{"Ar":"لا تخلط المنوال بالعدد الأكبر أو بتكراره.","En":"Do not confuse the mode with the largest value or its frequency."},"FormulaLatex":"f(v)=\\#\\{i:x_i=v\\}","Substitution":{"Ar":"$\\max(1,3,2)=3\\Rightarrow v=5$","En":"$\\max(1,3,2)=3\\Rightarrow v=5$"},"Verification":{"Ar":"$1+3+2=6$","En":"$1+3+2=6$"}},"TrackIds":[7],"CategoryId":22,"PrimarySkillId":299,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"أحص تكرار كل قيمة.","En":"Count each value's occurrences."},{"Ar":"قارن التكرارات واختر القيمة الموافقة للأكبر منها.","En":"Compare frequencies and select the value with the highest frequency."}],"Solution":{"Idea":{"Ar":"المنوال يحدد القيمة صاحبة التكرار الأكبر.","En":"The mode identifies the value with highest frequency."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نعد تكرار كل قيمة مختلفة في القائمة.","En":"Count occurrences of each distinct value in the list."},{"Ar":"$f(3)=1,\\ f(5)=3,\\ f(8)=2$","En":"$f(3)=1,\\ f(5)=3,\\ f(8)=2$"},{"Ar":"نختار القيمة ذات التكرار الأكبر، وليس عدد مرات التكرار نفسه.","En":"Choose the value with the largest frequency, not the frequency itself."}],"Result":{"Ar":"$5$","En":"$5$"},"CommonError":{"Ar":"لا تخلط المنوال بالعدد الأكبر أو بتكراره.","En":"Do not confuse the mode with the largest value or its frequency."},"FormulaLatex":"f(v)=\\#\\{i:x_i=v\\}","Substitution":{"Ar":"$\\max(1,3,2)=3\\Rightarrow v=5$","En":"$\\max(1,3,2)=3\\Rightarrow v=5$"},"Verification":{"Ar":"$1+3+2=6$","En":"$1+3+2=6$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"8 يتكرر مرتين فقط.","En":"Eight occurs only twice."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"3 يتكرر مرة واحدة فقط.","En":"Three occurs only once."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"6 عدد المشاهدات وليس قيمة متكررة.","En":"Six is the observation count, not a repeated value."},"Order":4}]}$mw$,$mw$المنوال يحدد القيمة صاحبة التكرار الأكبر.

$f(v)=\#\{i:x_i=v\}$

1. نعد تكرار كل قيمة مختلفة في القائمة.

2. $f(3)=1,\ f(5)=3,\ f(8)=2$

3. نختار القيمة ذات التكرار الأكبر، وليس عدد مرات التكرار نفسه.

$\max(1,3,2)=3\Rightarrow v=5$

$5$ بلا وحدة قياس

$1+3+2=6$

لا تخلط المنوال بالعدد الأكبر أو بتكراره.$mw$,$mw$The mode identifies the value with highest frequency.

$f(v)=\#\{i:x_i=v\}$

1. Count occurrences of each distinct value in the list.

2. $f(3)=1,\ f(5)=3,\ f(8)=2$

3. Choose the value with the largest frequency, not the frequency itself.

$\max(1,3,2)=3\Rightarrow v=5$

$5$ Dimensionless

$1+3+2=6$

Do not confuse the mode with the largest value or its frequency.$mw$),
(886,1642,$mw$02344CD355A2EB3790BAFDCCDD88D1092C239280F4705419FEBAEC019813221D$mw$,$mw$f74fbc0360556c51984cad3118be156f$mw$,$mw$$mw$,$mw${"Id":1642,"StageId":2,"CategoryId":22,"Points":10,"TitleAr":"القيم 4، 5، 6، 7، 8 متوسطها 6. إذا استُبدلت 8 بـ28، فما المتوسط الجديد؟","TitleEn":"Values 4, 5, 6, 7, 8 have mean 6. If 8 is replaced by 28, find the new mean.","QuestionTextAr":"القيم 4، 5، 6، 7، 8 متوسطها 6. إذا استُبدلت 8 بـ28، فما المتوسط الجديد؟","QuestionTextEn":"Values 4, 5, 6, 7, 8 have mean 6. If 8 is replaced by 28, find the new mean.","DetailedSolutionAr":"القانون المستخدم: المتوسط الجديد = مجموع القيم الجديدة ÷ عددها. مجموع القيم الأصلية 4 + 5 + 6 + 7 + 8 = 30. عند استبدال 8 بـ28 نطرح القديمة ونضيف الجديدة: 30 − 8 + 28 = 50. عدد القيم يبقى 5، لذا المتوسط الجديد = 50 ÷ 5 = 10.","DetailedSolutionEn":"Rule used: Mean = total sum ÷ number of observations. The original sum is 4 + 5 + 6 + 7 + 8 = 30. Replacing 8 with 28 increases the sum to 30 − 8 + 28 = 50, with the count still 5. Hence the new mean is 50 ÷ 5 = 10.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6557,"Order":1,"LatexCode":"6","IsCorrect":false},{"Id":6558,"Order":2,"LatexCode":"8","IsCorrect":false},{"Id":6559,"Order":3,"LatexCode":"10","IsCorrect":true},{"Id":6560,"Order":4,"LatexCode":"14","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"احسب أثر الاستبدال على المجموع.","En":"Find the effect of replacement on the total."},{"Ar":"اقسم تغير المجموع على عدد المشاهدات وأضفه إلى المتوسط القديم.","En":"Divide the change in total by the count and add to the old mean."}],"Title":{"Ar":"القيم 4، 5، 6، 7، 8 متوسطها 6. إذا استُبدلت 8 بـ28، فما المتوسط الجديد؟","En":"Values 4, 5, 6, 7, 8 have mean 6. If 8 is replaced by 28, find the new mean."},"Points":10,"Options":[{"LatexCode":"6","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"6 يتجاهل تغير إحدى المشاهدات.","En":"Six ignores the replacement."}},{"LatexCode":"8","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"8 يعطي مجموعاً قدره 40 بدلاً من 50.","En":"Eight implies a total of forty instead of fifty."}},{"LatexCode":"10","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"14","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"14 يعطي مجموعاً قدره 70 بدلاً من 50.","En":"Fourteen implies a total of seventy instead of fifty."}}],"StageId":2,"Question":{"Ar":"القيم 4، 5، 6، 7، 8 متوسطها 6. إذا استُبدلت 8 بـ28، فما المتوسط الجديد؟","En":"Values 4, 5, 6, 7, 8 have mean 6. If 8 is replaced by 28, find the new mean."},"Solution":{"Idea":{"Ar":"استبدال مشاهدة يغيّر المجموع بمقدار الفرق بين الجديدة والقديمة.","En":"Replacing an observation changes the total by the difference between new and old values."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"عدد المشاهدات يبقى خمسة، والمجموع القديم يساوي 30.","En":"The observation count remains five and the original sum is thirty."},{"Ar":"$5\\cdot6-8+28=50$","En":"$5\\cdot6-8+28=50$"},{"Ar":"استبدال 8 بـ28 يزيد المجموع بمقدار 20؛ نقسم المجموع الجديد على خمسة.","En":"Replacing eight by 28 increases the sum by twenty; divide the new total by five."}],"Result":{"Ar":"$10$","En":"$10$"},"CommonError":{"Ar":"لا تضف فرق المشاهدتين كاملاً إلى المتوسط.","En":"Do not add the entire change in observation value to the mean."},"FormulaLatex":"\\bar x_{\\rm new}=\\bar x_{\\rm old}+\\frac{b-a}{n}","Substitution":{"Ar":"$50/5=10$","En":"$50/5=10$"},"Verification":{"Ar":"$4+5+6+7+28=50$","En":"$4+5+6+7+28=50$"}},"TrackIds":[8],"CategoryId":22,"PrimarySkillId":299,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"احسب أثر الاستبدال على المجموع.","En":"Find the effect of replacement on the total."},{"Ar":"اقسم تغير المجموع على عدد المشاهدات وأضفه إلى المتوسط القديم.","En":"Divide the change in total by the count and add to the old mean."}],"Solution":{"Idea":{"Ar":"استبدال مشاهدة يغيّر المجموع بمقدار الفرق بين الجديدة والقديمة.","En":"Replacing an observation changes the total by the difference between new and old values."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"عدد المشاهدات يبقى خمسة، والمجموع القديم يساوي 30.","En":"The observation count remains five and the original sum is thirty."},{"Ar":"$5\\cdot6-8+28=50$","En":"$5\\cdot6-8+28=50$"},{"Ar":"استبدال 8 بـ28 يزيد المجموع بمقدار 20؛ نقسم المجموع الجديد على خمسة.","En":"Replacing eight by 28 increases the sum by twenty; divide the new total by five."}],"Result":{"Ar":"$10$","En":"$10$"},"CommonError":{"Ar":"لا تضف فرق المشاهدتين كاملاً إلى المتوسط.","En":"Do not add the entire change in observation value to the mean."},"FormulaLatex":"\\bar x_{\\rm new}=\\bar x_{\\rm old}+\\frac{b-a}{n}","Substitution":{"Ar":"$50/5=10$","En":"$50/5=10$"},"Verification":{"Ar":"$4+5+6+7+28=50$","En":"$4+5+6+7+28=50$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"6 يتجاهل تغير إحدى المشاهدات.","En":"Six ignores the replacement."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"8 يعطي مجموعاً قدره 40 بدلاً من 50.","En":"Eight implies a total of forty instead of fifty."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"14 يعطي مجموعاً قدره 70 بدلاً من 50.","En":"Fourteen implies a total of seventy instead of fifty."},"Order":4}]}$mw$,$mw$استبدال مشاهدة يغيّر المجموع بمقدار الفرق بين الجديدة والقديمة.

$\bar x_{\rm new}=\bar x_{\rm old}+\frac{b-a}{n}$

1. عدد المشاهدات يبقى خمسة، والمجموع القديم يساوي 30.

2. $5\cdot6-8+28=50$

3. استبدال 8 بـ28 يزيد المجموع بمقدار 20؛ نقسم المجموع الجديد على خمسة.

$50/5=10$

$10$ بلا وحدة قياس

$4+5+6+7+28=50$

لا تضف فرق المشاهدتين كاملاً إلى المتوسط.$mw$,$mw$Replacing an observation changes the total by the difference between new and old values.

$\bar x_{\rm new}=\bar x_{\rm old}+\frac{b-a}{n}$

1. The observation count remains five and the original sum is thirty.

2. $5\cdot6-8+28=50$

3. Replacing eight by 28 increases the sum by twenty; divide the new total by five.

$50/5=10$

$10$ Dimensionless

$4+5+6+7+28=50$

Do not add the entire change in observation value to the mean.$mw$),
(888,1644,$mw$11C85108187E41340A74F604E9745FBCA85B8DE2DF0EFBFCE1165F816E143EF4$mw$,$mw$a682ab18659bafaf9dffe5031c692aaa$mw$,$mw$$mw$,$mw${"Id":1644,"StageId":3,"CategoryId":23,"Points":10,"TitleAr":"المتسلسلة $\\sum_{n=0}^{\\infty}(1.1)^n$ متباعدة. أي شرط يدل على ذلك؟","TitleEn":"The series $\\sum_{n=0}^{\\infty}(1.1)^n$ diverges. Which ratio condition explains why?","QuestionTextAr":"المتسلسلة $\\sum_{n=0}^{\\infty}(1.1)^n$ متباعدة. أي شرط يدل على ذلك؟","QuestionTextEn":"The series $\\sum_{n=0}^{\\infty}(1.1)^n$ diverges. Which ratio condition explains why?","DetailedSolutionAr":"القانون المستخدم: تتقارب المتسلسلة الهندسية اللانهائية ذات النسبة r فقط عندما |r| أقل من 1. هنا حدود المتسلسلة هي (1.1)^ن، والنسبة المشتركة r = 1.1. بما أن |1.1| = 1.1 أكبر من 1، لا تقترب الحدود من الصفر، لذلك تتباعد المتسلسلة والشرط المفسر هو |r| > 1.","DetailedSolutionEn":"Rule used: An infinite geometric series converges exactly when the absolute value of its common ratio is below 1. In this series r = 1.1, so |r| = 1.1 > 1. Its terms do not approach zero and its sum diverges. The correct condition is |r| > 1.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6565,"Order":1,"LatexCode":"|r|<1","IsCorrect":false},{"Id":6566,"Order":2,"LatexCode":"r=\\frac12","IsCorrect":false},{"Id":6567,"Order":3,"LatexCode":"r=0","IsCorrect":false},{"Id":6568,"Order":4,"LatexCode":"|r|>1","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"استخرج النسبة الهندسية من الحد العام.","En":"Identify the geometric ratio from the general term."},{"Ar":"قارن القيمة المطلقة للنسبة بالواحد.","En":"Compare the absolute ratio with one."}],"Title":{"Ar":"المتسلسلة $\\sum_{n=0}^{\\infty}(1.1)^n$ متباعدة. أي شرط يدل على ذلك؟","En":"The series $\\sum_{n=0}^{\\infty}(1.1)^n$ diverges. Which ratio condition explains why?"},"Points":10,"Options":[{"LatexCode":"|r|<1","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"هذا شرط التقارب وليس حالة النسبة المعطاة.","En":"This is the convergence condition, not the given ratio case."}},{"LatexCode":"r=\\frac12","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"النسبة المعطاة 1.1 وليست نصفاً.","En":"The given ratio is 1.1, not one half."}},{"LatexCode":"r=0","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"النسبة ليست صفراً.","En":"The ratio is not zero."}},{"LatexCode":"|r|>1","IsCorrect":true,"ErrorType":"","Reason":null}],"StageId":3,"Question":{"Ar":"المتسلسلة $\\sum_{n=0}^{\\infty}(1.1)^n$ متباعدة. أي شرط يدل على ذلك؟","En":"The series $\\sum_{n=0}^{\\infty}(1.1)^n$ diverges. Which ratio condition explains why?"},"Solution":{"Idea":{"Ar":"تقارب المتسلسلة الهندسية غير الصفرية يتطلب أن تكون القيمة المطلقة للنسبة أصغر من واحد.","En":"A nonzero geometric series converges only if the absolute ratio is less than one."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الحد الأول واحد والنسبة الهندسية 1.1؛ لذا لا تتناقص الحدود نحو الصفر.","En":"The first term is one and the common ratio is 1.1; the terms do not tend to zero."},{"Ar":"$r=1.1,\\quad|r|=1.1>1$","En":"$r=1.1,\\quad|r|=1.1>1$"},{"Ar":"شرط التقارب هو أن يكون مقدار النسبة أصغر من واحد. هنا المقدار أكبر من واحد، فتتباعد المتسلسلة.","En":"Convergence requires the ratio magnitude to be below one. Here it exceeds one, so the series diverges."}],"Result":{"Ar":"$|r|>1$","En":"$|r|>1$"},"CommonError":{"Ar":"لا تطبق صيغة المجموع اللانهائي عندما يفشل شرط التقارب؛ والمقدار المساوي لواحد يتباعد أيضاً هنا للحد الأول غير الصفري.","En":"Do not apply the infinite-sum formula outside its convergence condition; magnitude one also causes divergence for a nonzero initial term."},"FormulaLatex":"|r|<1","Substitution":{"Ar":"$\\lim_{n\\to\\infty}(1.1)^n=+\\infty$","En":"$\\lim_{n\\to\\infty}(1.1)^n=+\\infty$"},"Verification":{"Ar":"$S_N=\\frac{1.1^{N+1}-1}{0.1}\\to+\\infty$","En":"$S_N=\\frac{1.1^{N+1}-1}{0.1}\\to+\\infty$"}},"TrackIds":[12],"CategoryId":23,"PrimarySkillId":300,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"استخرج النسبة الهندسية من الحد العام.","En":"Identify the geometric ratio from the general term."},{"Ar":"قارن القيمة المطلقة للنسبة بالواحد.","En":"Compare the absolute ratio with one."}],"Solution":{"Idea":{"Ar":"تقارب المتسلسلة الهندسية غير الصفرية يتطلب أن تكون القيمة المطلقة للنسبة أصغر من واحد.","En":"A nonzero geometric series converges only if the absolute ratio is less than one."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الحد الأول واحد والنسبة الهندسية 1.1؛ لذا لا تتناقص الحدود نحو الصفر.","En":"The first term is one and the common ratio is 1.1; the terms do not tend to zero."},{"Ar":"$r=1.1,\\quad|r|=1.1>1$","En":"$r=1.1,\\quad|r|=1.1>1$"},{"Ar":"شرط التقارب هو أن يكون مقدار النسبة أصغر من واحد. هنا المقدار أكبر من واحد، فتتباعد المتسلسلة.","En":"Convergence requires the ratio magnitude to be below one. Here it exceeds one, so the series diverges."}],"Result":{"Ar":"$|r|>1$","En":"$|r|>1$"},"CommonError":{"Ar":"لا تطبق صيغة المجموع اللانهائي عندما يفشل شرط التقارب؛ والمقدار المساوي لواحد يتباعد أيضاً هنا للحد الأول غير الصفري.","En":"Do not apply the infinite-sum formula outside its convergence condition; magnitude one also causes divergence for a nonzero initial term."},"FormulaLatex":"|r|<1","Substitution":{"Ar":"$\\lim_{n\\to\\infty}(1.1)^n=+\\infty$","En":"$\\lim_{n\\to\\infty}(1.1)^n=+\\infty$"},"Verification":{"Ar":"$S_N=\\frac{1.1^{N+1}-1}{0.1}\\to+\\infty$","En":"$S_N=\\frac{1.1^{N+1}-1}{0.1}\\to+\\infty$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"هذا شرط التقارب وليس حالة النسبة المعطاة.","En":"This is the convergence condition, not the given ratio case."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"النسبة المعطاة 1.1 وليست نصفاً.","En":"The given ratio is 1.1, not one half."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"النسبة ليست صفراً.","En":"The ratio is not zero."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$تقارب المتسلسلة الهندسية غير الصفرية يتطلب أن تكون القيمة المطلقة للنسبة أصغر من واحد.

$|r|<1$

1. الحد الأول واحد والنسبة الهندسية 1.1؛ لذا لا تتناقص الحدود نحو الصفر.

2. $r=1.1,\quad|r|=1.1>1$

3. شرط التقارب هو أن يكون مقدار النسبة أصغر من واحد. هنا المقدار أكبر من واحد، فتتباعد المتسلسلة.

$\lim_{n\to\infty}(1.1)^n=+\infty$

$|r|>1$ بلا وحدة قياس

$S_N=\frac{1.1^{N+1}-1}{0.1}\to+\infty$

لا تطبق صيغة المجموع اللانهائي عندما يفشل شرط التقارب؛ والمقدار المساوي لواحد يتباعد أيضاً هنا للحد الأول غير الصفري.$mw$,$mw$A nonzero geometric series converges only if the absolute ratio is less than one.

$|r|<1$

1. The first term is one and the common ratio is 1.1; the terms do not tend to zero.

2. $r=1.1,\quad|r|=1.1>1$

3. Convergence requires the ratio magnitude to be below one. Here it exceeds one, so the series diverges.

$\lim_{n\to\infty}(1.1)^n=+\infty$

$|r|>1$ Dimensionless

$S_N=\frac{1.1^{N+1}-1}{0.1}\to+\infty$

Do not apply the infinite-sum formula outside its convergence condition; magnitude one also causes divergence for a nonzero initial term.$mw$),
(890,1646,$mw$7C16B11BFF3994F065E125B187A57EE3921D95159F04B5E9E6D08921242C33A3$mw$,$mw$622fab576d6d557121f0bca586724184$mw$,$mw$$mw$,$mw${"Id":1646,"StageId":3,"CategoryId":23,"Points":10,"TitleAr":"لماذا تتباعد المتسلسلة $\\sum_{n=1}^{\\infty}2$؟","TitleEn":"Why does the series $\\sum_{n=1}^{\\infty}2$ diverge?","QuestionTextAr":"لماذا تتباعد المتسلسلة $\\sum_{n=1}^{\\infty}2$؟","QuestionTextEn":"Why does the series $\\sum_{n=1}^{\\infty}2$ diverge?","DetailedSolutionAr":"المبدأ المستخدم: اختبار الحد العام الضروري للتقارب يقول إنه إذا كانت المتسلسلة ∑aₙ متقاربة، فلا بد أن تؤول حدودها aₙ إلى الصفر. هنا aₙ = 2 لكل ن، وبالتالي النهاية عندما ن تؤول للمالانهاية هي 2، وليست صفراً. إذن يفشل شرط التقارب الضروري وتكون المتسلسلة متباعدة.","DetailedSolutionEn":"Rule used: The nth-term divergence test states that convergence of a series ∑a_n requires its terms a_n to approach zero. Here a_n = 2 for every n, so lim(n→∞) a_n = 2 ≠ 0. The necessary condition for convergence fails, proving that the series diverges.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6573,"Order":1,"LatexCode":"\\lim_{n\\to\\infty}a_n=0","IsCorrect":false},{"Id":6574,"Order":2,"LatexCode":"\\lim_{n\\to\\infty}a_n=2","IsCorrect":true},{"Id":6575,"Order":3,"LatexCode":"|r|<1","IsCorrect":false},{"Id":6576,"Order":4,"LatexCode":"a_1=0","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"افحص الحد العام قبل المجموع.","En":"Examine the individual term before the sum."},{"Ar":"احسب نهاية الحد الثابت وطبّق الشرط اللازم للتقارب.","En":"Find the constant term's limit and apply the necessary convergence condition."}],"Title":{"Ar":"لماذا تتباعد المتسلسلة $\\sum_{n=1}^{\\infty}2$؟","En":"Why does the series $\\sum_{n=1}^{\\infty}2$ diverge?"},"Points":10,"Options":[{"LatexCode":"\\lim_{n\\to\\infty}a_n=0","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"نهاية الحدود 2 لا صفر.","En":"The term limit is two, not zero."}},{"LatexCode":"\\lim_{n\\to\\infty}a_n=2","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"|r|<1","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"النسبة بين حدين متتاليين تساوي 1.","En":"The ratio of successive terms is one."}},{"LatexCode":"a_1=0","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"الحد الأول 2 لا صفر.","En":"The first term is two, not zero."}}],"StageId":3,"Question":{"Ar":"لماذا تتباعد المتسلسلة $\\sum_{n=1}^{\\infty}2$؟","En":"Why does the series $\\sum_{n=1}^{\\infty}2$ diverge?"},"Solution":{"Idea":{"Ar":"الحد العام لا بد أن يقترب من الصفر إذا تقاربت المتسلسلة.","En":"A convergent series must have terms tending to zero."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"إذا تقارب المجموع الجزئي فإن الفرق بين مجموعين جزئيين متتاليين يؤول إلى الصفر.","En":"If partial sums converge, the difference between consecutive partial sums tends to zero."},{"Ar":"$a_n=2,\\quad S_N=2N$","En":"$a_n=2,\\quad S_N=2N$"},{"Ar":"الحدود هنا ثابتة عند 2، فلا يتحقق الشرط اللازم للتقارب.","En":"Here the terms are constantly two, so the necessary convergence condition fails."}],"Result":{"Ar":"$\\lim_{n\\to\\infty}a_n=2$","En":"$\\lim_{n\\to\\infty}a_n=2$"},"CommonError":{"Ar":"اقتراب الحدود من الصفر شرط لازم وليس كافياً لتقارب المتسلسلة.","En":"Terms tending to zero is necessary but not sufficient for series convergence."},"FormulaLatex":"S_N=\\sum_{n=1}^N a_n,\\quad a_n=S_n-S_{n-1}","Substitution":{"Ar":"$\\lim_{n\\to\\infty}a_n=2\\ne0$","En":"$\\lim_{n\\to\\infty}a_n=2\\ne0$"},"Verification":{"Ar":"$\\lim_{N\\to\\infty}2N=+\\infty$","En":"$\\lim_{N\\to\\infty}2N=+\\infty$"}},"TrackIds":[12],"CategoryId":23,"PrimarySkillId":300,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"افحص الحد العام قبل المجموع.","En":"Examine the individual term before the sum."},{"Ar":"احسب نهاية الحد الثابت وطبّق الشرط اللازم للتقارب.","En":"Find the constant term's limit and apply the necessary convergence condition."}],"Solution":{"Idea":{"Ar":"الحد العام لا بد أن يقترب من الصفر إذا تقاربت المتسلسلة.","En":"A convergent series must have terms tending to zero."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"إذا تقارب المجموع الجزئي فإن الفرق بين مجموعين جزئيين متتاليين يؤول إلى الصفر.","En":"If partial sums converge, the difference between consecutive partial sums tends to zero."},{"Ar":"$a_n=2,\\quad S_N=2N$","En":"$a_n=2,\\quad S_N=2N$"},{"Ar":"الحدود هنا ثابتة عند 2، فلا يتحقق الشرط اللازم للتقارب.","En":"Here the terms are constantly two, so the necessary convergence condition fails."}],"Result":{"Ar":"$\\lim_{n\\to\\infty}a_n=2$","En":"$\\lim_{n\\to\\infty}a_n=2$"},"CommonError":{"Ar":"اقتراب الحدود من الصفر شرط لازم وليس كافياً لتقارب المتسلسلة.","En":"Terms tending to zero is necessary but not sufficient for series convergence."},"FormulaLatex":"S_N=\\sum_{n=1}^N a_n,\\quad a_n=S_n-S_{n-1}","Substitution":{"Ar":"$\\lim_{n\\to\\infty}a_n=2\\ne0$","En":"$\\lim_{n\\to\\infty}a_n=2\\ne0$"},"Verification":{"Ar":"$\\lim_{N\\to\\infty}2N=+\\infty$","En":"$\\lim_{N\\to\\infty}2N=+\\infty$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"نهاية الحدود 2 لا صفر.","En":"The term limit is two, not zero."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"النسبة بين حدين متتاليين تساوي 1.","En":"The ratio of successive terms is one."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"الحد الأول 2 لا صفر.","En":"The first term is two, not zero."},"Order":4}]}$mw$,$mw$الحد العام لا بد أن يقترب من الصفر إذا تقاربت المتسلسلة.

$S_N=\sum_{n=1}^N a_n,\quad a_n=S_n-S_{n-1}$

1. إذا تقارب المجموع الجزئي فإن الفرق بين مجموعين جزئيين متتاليين يؤول إلى الصفر.

2. $a_n=2,\quad S_N=2N$

3. الحدود هنا ثابتة عند 2، فلا يتحقق الشرط اللازم للتقارب.

$\lim_{n\to\infty}a_n=2\ne0$

$\lim_{n\to\infty}a_n=2$ بلا وحدة قياس

$\lim_{N\to\infty}2N=+\infty$

اقتراب الحدود من الصفر شرط لازم وليس كافياً لتقارب المتسلسلة.$mw$,$mw$A convergent series must have terms tending to zero.

$S_N=\sum_{n=1}^N a_n,\quad a_n=S_n-S_{n-1}$

1. If partial sums converge, the difference between consecutive partial sums tends to zero.

2. $a_n=2,\quad S_N=2N$

3. Here the terms are constantly two, so the necessary convergence condition fails.

$\lim_{n\to\infty}a_n=2\ne0$

$\lim_{n\to\infty}a_n=2$ Dimensionless

$\lim_{N\to\infty}2N=+\infty$

Terms tending to zero is necessary but not sufficient for series convergence.$mw$),
(891,1647,$mw$AB04D120F89448D7F25B038ECD8E891E1EE5968E1C63E51E62238294FBBCC674$mw$,$mw$b660de0b46d9d7650c527618b00c73d7$mw$,$mw$$mw$,$mw${"Id":1647,"StageId":4,"CategoryId":24,"Points":10,"TitleAr":"ما النفي المنطقي لعبارة $\\forall x\\,P(x)$؟","TitleEn":"What is the logical negation of $\\forall x\\,P(x)$?","QuestionTextAr":"ما النفي المنطقي لعبارة $\\forall x\\,P(x)$؟","QuestionTextEn":"What is the logical negation of $\\forall x\\,P(x)$?","DetailedSolutionAr":"القانون المستخدم: نفي العبارة الكلية يبدّل «لكل» إلى «يوجد» وينفي الخاصية نفسها: ¬(∀س P(س)) ⇔ ∃س ¬P(س). لنفي أن كل س يحقق P لا نحتاج إثبات أن كل القيم تخالفها؛ تكفي قيمة واحدة لا تحقق P. إذن النفي الصحيح هو ∃س ¬P(س).","DetailedSolutionEn":"Rule used: Quantifier-negation law: ¬(∀x P(x)) is logically equivalent to ∃x ¬P(x). Saying that 'every x satisfies P' is false means there exists at least one counterexample where P(x) is false. Therefore the correct negation is ∃x ¬P(x).","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6577,"Order":1,"LatexCode":"\\forall x\\,\\neg P(x)","IsCorrect":false},{"Id":6578,"Order":2,"LatexCode":"\\exists x\\,\\neg P(x)","IsCorrect":true},{"Id":6579,"Order":3,"LatexCode":"\\exists x\\,P(x)","IsCorrect":false},{"Id":6580,"Order":4,"LatexCode":"\\neg\\exists x\\,\\neg P(x)","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"نفي التكميم الكلي يحول العبارة إلى تكميم وجودي.","En":"Negating a universal quantifier changes it to an existential quantifier."},{"Ar":"انقل النفي إلى داخل العبارة مع تبديل نوع المكمم.","En":"Move negation inside the predicate while switching the quantifier."}],"Title":{"Ar":"ما النفي المنطقي لعبارة $\\forall x\\,P(x)$؟","En":"What is the logical negation of $\\forall x\\,P(x)$?"},"Points":10,"Options":[{"LatexCode":"\\forall x\\,\\neg P(x)","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"هذا يشترط فشل المحمول لكل العناصر، وهو أقوى من النفي المطلوب.","En":"This requires failure for every element, which is stronger than the required negation."}},{"LatexCode":"\\exists x\\,\\neg P(x)","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"\\exists x\\,P(x)","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"هذا يثبت وجود عنصر يحقق المحمول لا عنصر يخالفه.","En":"This asserts an element satisfies the predicate rather than violates it."}},{"LatexCode":"\\neg\\exists x\\,\\neg P(x)","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"هذا ينفي وجود مثال مضاد، وهو مكافئ للعبارة الأصلية.","En":"This denies the existence of a counterexample and is equivalent to the original."}}],"StageId":4,"Question":{"Ar":"ما النفي المنطقي لعبارة $\\forall x\\,P(x)$؟","En":"What is the logical negation of $\\forall x\\,P(x)$?"},"Solution":{"Idea":{"Ar":"نفي الكلي يحول الكم إلى وجودي وينفي المحمول.","En":"Negating a universal quantifier changes it to existential and negates the predicate."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"عدم صحة العبارة لكل عناصر المجال يعني وجود عنصر واحد على الأقل يفشل عنده المحمول.","En":"Failure of a statement for every element means at least one element fails the predicate."},{"Ar":"$\\neg\\forall x\\,P(x)$","En":"$\\neg\\forall x\\,P(x)$"},{"Ar":"نبدل الكم الكلي بالوجودي وننقل النفي إلى المحمول مع بقاء المجال نفسه.","En":"Switch the universal quantifier to an existential quantifier and negate the predicate over the same domain."}],"Result":{"Ar":"$\\exists x\\,\\neg P(x)$","En":"$\\exists x\\,\\neg P(x)$"},"CommonError":{"Ar":"لا تبدل المكمم دون نفي المحمول.","En":"Do not switch the quantifier without negating the predicate."},"FormulaLatex":"\\neg(\\forall x\\,P(x))\\equiv\\exists x\\,\\neg P(x)","Substitution":{"Ar":"$\\exists x\\,\\neg P(x)$","En":"$\\exists x\\,\\neg P(x)$"},"Verification":{"Ar":"$D=\\{1,2\\},\\ P(x):x>1,\\quad \\neg P(1)$","En":"$D=\\{1,2\\},\\ P(x):x>1,\\quad \\neg P(1)$"}},"TrackIds":[17,20],"CategoryId":24,"PrimarySkillId":301,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"نفي التكميم الكلي يحول العبارة إلى تكميم وجودي.","En":"Negating a universal quantifier changes it to an existential quantifier."},{"Ar":"انقل النفي إلى داخل العبارة مع تبديل نوع المكمم.","En":"Move negation inside the predicate while switching the quantifier."}],"Solution":{"Idea":{"Ar":"نفي الكلي يحول الكم إلى وجودي وينفي المحمول.","En":"Negating a universal quantifier changes it to existential and negates the predicate."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"عدم صحة العبارة لكل عناصر المجال يعني وجود عنصر واحد على الأقل يفشل عنده المحمول.","En":"Failure of a statement for every element means at least one element fails the predicate."},{"Ar":"$\\neg\\forall x\\,P(x)$","En":"$\\neg\\forall x\\,P(x)$"},{"Ar":"نبدل الكم الكلي بالوجودي وننقل النفي إلى المحمول مع بقاء المجال نفسه.","En":"Switch the universal quantifier to an existential quantifier and negate the predicate over the same domain."}],"Result":{"Ar":"$\\exists x\\,\\neg P(x)$","En":"$\\exists x\\,\\neg P(x)$"},"CommonError":{"Ar":"لا تبدل المكمم دون نفي المحمول.","En":"Do not switch the quantifier without negating the predicate."},"FormulaLatex":"\\neg(\\forall x\\,P(x))\\equiv\\exists x\\,\\neg P(x)","Substitution":{"Ar":"$\\exists x\\,\\neg P(x)$","En":"$\\exists x\\,\\neg P(x)$"},"Verification":{"Ar":"$D=\\{1,2\\},\\ P(x):x>1,\\quad \\neg P(1)$","En":"$D=\\{1,2\\},\\ P(x):x>1,\\quad \\neg P(1)$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"هذا يشترط فشل المحمول لكل العناصر، وهو أقوى من النفي المطلوب.","En":"This requires failure for every element, which is stronger than the required negation."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"هذا يثبت وجود عنصر يحقق المحمول لا عنصر يخالفه.","En":"This asserts an element satisfies the predicate rather than violates it."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"هذا ينفي وجود مثال مضاد، وهو مكافئ للعبارة الأصلية.","En":"This denies the existence of a counterexample and is equivalent to the original."},"Order":4}]}$mw$,$mw$نفي الكلي يحول الكم إلى وجودي وينفي المحمول.

$\neg(\forall x\,P(x))\equiv\exists x\,\neg P(x)$

1. عدم صحة العبارة لكل عناصر المجال يعني وجود عنصر واحد على الأقل يفشل عنده المحمول.

2. $\neg\forall x\,P(x)$

3. نبدل الكم الكلي بالوجودي وننقل النفي إلى المحمول مع بقاء المجال نفسه.

$\exists x\,\neg P(x)$

$\exists x\,\neg P(x)$ بلا وحدة محددة

$D=\{1,2\},\ P(x):x>1,\quad \neg P(1)$

لا تبدل المكمم دون نفي المحمول.$mw$,$mw$Negating a universal quantifier changes it to existential and negates the predicate.

$\neg(\forall x\,P(x))\equiv\exists x\,\neg P(x)$

1. Failure of a statement for every element means at least one element fails the predicate.

2. $\neg\forall x\,P(x)$

3. Switch the universal quantifier to an existential quantifier and negate the predicate over the same domain.

$\exists x\,\neg P(x)$

$\exists x\,\neg P(x)$ No specified unit

$D=\{1,2\},\ P(x):x>1,\quad \neg P(1)$

Do not switch the quantifier without negating the predicate.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
